/*
 * A036552  List of pairs (m,2m) where m is the least unused positive number.
 * https://oeis.org/A036552
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy, nice
 * Formula:   not stated
 * Range:     u8 n <= 171, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  OEIS A036552 – permutation generated by repeatedly taking the
    smallest unused integer m and outputting m followed by 2*m.
    This implementation builds the sequence on demand, caching
    previously computed terms.  It works for any index n >= 1
    and on any order of calls.  All intermediate values fit in
    the chosen integer width. */
#include <stdint.h>
#include <stddef.h>
#include <stdlib.h>
#include <string.h>

static seq_t *seq = NULL;          /* cache of sequence values   */
static size_t seq_cap = 0;         /* allocated capacity        */
static size_t seq_len = 0;         /* number of values cached   */

static uint8_t *used = NULL;       /* boolean array of used ints */
static size_t used_cap = 0;        /* used array capacity       */
static idx_t next_candidate = 1;   /* next integer to try for m */

/* Ensure that seq has room for at least 'need' elements. */
static void ensure_seq_capacity(size_t need)
{
    if (need <= seq_cap) return;
    size_t new_cap = seq_cap ? seq_cap << 1 : 8;
    while (new_cap < need) new_cap <<= 1;
    seq = (seq_t *)realloc(seq, new_cap * sizeof(seq_t));
    seq_cap = new_cap;
}

/* Ensure that the used array covers index 'idx'. */
static void ensure_used_capacity(idx_t idx)
{
    if (idx < (idx_t)used_cap) return;
    size_t new_cap = used_cap ? used_cap << 1 : 8;
    while (new_cap <= (size_t)idx) new_cap <<= 1;
    used = (uint8_t *)realloc(used, new_cap * sizeof(uint8_t));
    memset(used + used_cap, 0, (new_cap - used_cap) * sizeof(uint8_t));
    used_cap = new_cap;
}

/* Generate terms until seq_len >= n (1‑based). */
static void gen_more(idx_t n)
{
    while ((size_t)n > seq_len) {
        /* Find the least unused integer m. */
        while (next_candidate < (idx_t)used_cap && used[(size_t)next_candidate]) {
            ++next_candidate;
        }
        if (next_candidate >= (idx_t)used_cap)
            ensure_used_capacity(next_candidate);

        idx_t m = next_candidate;
        idx_t twice = m << 1;          /* 2*m */

        /* Make sure we can mark 2*m as used. */
        if (twice >= (idx_t)used_cap)
            ensure_used_capacity(twice);

        /* Append m and 2*m to the sequence. */
        ensure_seq_capacity(seq_len + 2);
        seq[seq_len]     = (seq_t)m;
        seq[seq_len + 1] = (seq_t)twice;
        seq_len += 2;

        /* Mark both numbers as used. */
        used[(size_t)m]     = 1;
        used[(size_t)twice] = 1;

        ++next_candidate;
    }
}

seq_t a(idx_t n)
{
    if (n == 0) return 0;                 /* undefined for n==0 */
    if (n > seq_len) gen_more(n);           /* generate up to n */
    return seq[n - 1];                     /* 0‑based indexing */
}
